-- Atomic & Durable Transfer
BEGIN TRANSACTION;
  UPDATE accounts SET balance = balance - 100 WHERE id = 'A';
  UPDATE accounts SET balance = balance + 100 WHERE id = 'B';
COMMIT; -- Flushed to WAL on disk

-- Composite Index Creation
CREATE INDEX idx_users_org_created ON users(org_id, created_at);

-- Uses index efficiently (Leftmost Prefix Rule)
SELECT * FROM users WHERE org_id = '101' AND created_at > '2026-01-01';
